sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Type appropriate comment here, and begin script below
    var employee = g_form.getValue('employee');
	// var startStr = g_form.getValue('start_date');
	// var endStr = g_form.getValue('end_date');
	var leaveType = g_form.getValue('leave_type');

	// var startDate = getDateFromFormat(startStr, g_user_date_format);
    // var endDate = getDateFromFormat(endStr, g_user_date_format);

    // Calculate the difference in days
    // var diffInMs = endDate - startDate;
    // var days = diffInMs / (1000 * 60 * 60 * 24);

	// alert("leaveType: "+ leaveType);

	// var days = g_form.getValue('number_of_leave_days');

	var ga = new GlideAjax('leaveHandlerUtils');
	ga.addParam('sysparm_name', 'balanceLeave');
	ga.addParam('employee_name', employee);
	ga.addParam('leave_type', leaveType);
	ga.addParam('current_days', newValue);
	ga.getXMLAnswer(leaveCalculation);
}

function leaveCalculation(leaveBalance){
	// alert(leaveBalance);
	g_form.setValue('leave_balance', parseInt(leaveBalance));
}
